/** What video.generate takes. */
export interface VideoGenerateReq {
  /**
   * a group inside the project, held or cleared together
   * @maxLength 60
   */
  batch?: string | null;
  /** a camera name: prev_cam / first_cam anchor on the series' clips of the same camera */
  camera?: string | null;
  /**
   * the clip's place in its project's timeline (1 and up). Say it: without it the timeline reads the label's NN/MM, else the #N of reentrant_id
   * @minimum 1
   * @maximum 100000
   */
  clip?: number | null;
  /**
   * how the clip carries on from another, as one object (it sets guide_clip, first_audio, first_audio_s, first_frame, chain_mode, exposure_ref; those given flat win). There is no renormalisation step here: pin_renorm and other keys are listed back in ignored
   * @properties {"color_reanchor":{"description":"true (= from), an anchor or a picture: the carried pictures scaled to its brightness (exposure_ref) - gain 0.75-1.35 on luminance, against drift"},"context_frames":{"description":"0 or 17k + 5 (22 = 0.92 s): the last N frames of from as one moving keyframe at frame 0 (guide_clip) - the clip replays them, so trim N/2 each side at the join","type":"integer"},"from":{"default":"prev","description":"anchor or file: the clip carried on from","type":"string"},"mode":{"description":"still: chain_mode","enum":["video","png","latent"],"type":"string"},"sound":{"default":true,"description":"with context_frames: the sound's last N/24 s too (first_audio, first_audio_s)","type":"boolean"},"still":{"description":"from's last frame as the first frame (first_frame); default: when context_frames is 0","type":"boolean"}}
   */
  chain?: Record<string, unknown> | null;
  /**
   * how a first_frame clip is carried over: its mp4's last frame, its lossless .last.png, its last latent, or not at all
   * @default "video"
   */
  chain_mode?: ChainMode | null;
  /** noise on the first frame (harmful here: shows as confetti) */
  cond_noise_aug?: number | null;
  /**
   *
   * @minimum 0
   * @maximum 1
   * @default 1
   */
  control_end?: number | null;
  /** a mask clip or picture (file): regenerate inside it */
  control_mask?: string | null;
  /** the clip the mask applies to (file) */
  control_source?: string | null;
  /**
   * the part of the steps the control steers
   * @minimum 0
   * @maximum 1
   * @default 0
   */
  control_start?: number | null;
  /**
   *
   * @minimum 0
   * @maximum 10
   * @default 1
   */
  control_strength?: number | null;
  /** a ControlNet control clip (file); not with Ref2VA */
  control_video?: string | null;
  /**
   * the denoiser, by video.engines.list's quant (Q8_0 is read as INT8); REF2VA is chosen by itself when ref_images or ref_videos are given
   * @default "INT8"
   */
  engine?: string | null;
  /** anchor or file: a picture whose exposure and colour the clip keeps */
  exposure_ref?: string | null;
  /** anchor or file: the sound the clip continues from */
  first_audio?: string | null;
  /** seconds of first_audio to continue from */
  first_audio_s?: number | null;
  /** file: a driving soundtrack (a song, video.upload): the clip's length of it from soundtrack_start pinned under the whole clip as an audio keyframe - the picture is made to it (a singer's mouth to the singing) and the clip carries the file's own sound. Not with first_audio; a chain carries the picture only. For a whole song: a chain of clips, each from where its first frame is in the song (the previous start + (frames - context_frames) / 24), joined, the song laid under the join */
  soundtrack?: string | null;
  /**
   * seconds into the soundtrack at the clip's first frame (default 0)
   * @minimum 0
   * @default 0
   */
  soundtrack_start?: number | null;
  /** anchor or file: the clip starts on this picture / clip's last frame */
  first_frame?: string | null;
  /**
   * the length exactly, instead of seconds: 17k + 5 (22, 39, 56 ... 107, 124 ... 362); another count is refused, the message naming the nearest two
   * @minimum 22
   * @maximum 362
   */
  frames?: number | null;
  /** a motion guide: "<anchor or file>[:frames[:at]]" - the last frames of a clip as one moving keyframe */
  guide_clip?: string | null;
  /**
   * as width
   * @minimum 256
   * @maximum 1344
   * @default 576
   * @multipleOf 32
   */
  height?: number | null;
  /**
   * "<series> NN/MM: text", e.g. "Harbour 03/12: the lamp": NN is the clip's place in video.timeline (the edit order), the text before it the series the anchors prev / first look in and the project when none is given. Letters, digits, _ and  -.,:'()!?/ only (others are dropped); labels name clips for video.cancel, video.queue.move and video.queue.remove
   * @maxLength 80
   */
  label?: string | null;
  /** anchor or file: the clip ends on this picture (prev: the newest clip anywhere) */
  last_frame?: string | null;
  /**
   * "path:strength"
   * @items {"maxLength":200,"type":"string"}
   */
  loras?: string[] | null;
  /** ignored: H3 runs at cfg 1 (one pass a step, no unconditional branch), so a negative prompt has nothing to steer - say what is there instead (negations render). Accepted and listed in the answer's ignored */
  negative_prompt?: string | null;
  /**
   * a queued clip goes ahead of every clip of a lower priority (same priority: first come first made)
   * @minimum -9
   * @maximum 9
   * @default 0
   */
  priority?: number | null;
  /**
   * default: the label's series
   * @maxLength 60
   */
  project?: string | null;
  /** read as written - tokenized whole, no template, no sections parsed. H3 was trained on three fields in a fixed order: integrated_multimodal_description (shots, actions, camera, dialogue), overall_soundscape, non_diegetic_music; video.describePromptGuideMD has the form and its rules */
  prompt: string;
  /**
   * queue the clip when the studio is busy (false: 409 busy)
   * @default false
   */
  queue?: boolean | null;
  /**
   * idempotent submit: a clip of this id queued, running or made is answered (reentered: true) instead of a new one; a failed one is made again
   * @maxLength 200
   */
  reentrant_id?: string | null;
  /**
   * voices to speak in: <Audio 1> ... in the prompt
   * @maxItems 3
   */
  ref_audios?: string[] | null;
  /** reference pictures resized to the canvas, or kept as large as fits */
  ref_image_size?: RefImageSize | null;
  /**
   * Ref2VA reference pictures (files in the clips directory), <Image 1> ... in the prompt
   * @maxItems 9
   */
  ref_images?: string[] | null;
  /** the reference clips' sound too */
  ref_video_sound?: boolean | null;
  /**
   * Ref2VA reference clips
   * @maxItems 3
   */
  ref_videos?: string[] | null;
  /** "from-to" seconds to regenerate in source; a source shorter than the clip is extended */
  regen?: string | null;
  /** "x0,y0,x1,y1" pixels: regenerate only inside */
  regen_box?: string | null;
  /** ComfyUI's name (none: the engine's own Euler) */
  sampler?: string | null;
  /** ComfyUI's name */
  schedule?: string | null;
  /**
   * length; snapped up to the model's frame grid (17k + 5 frames at 24 fps: 4 s -> 107 frames); the model is trained on 5.2-15.1 s. The answer's frames and seconds say what is made
   * @minimum 1
   * @maximum 15.1
   * @default 10
   */
  seconds?: number | null;
  /**
   *
   * @minimum -2147483648
   * @maximum 2147483648
   * @default 0
   */
  seed?: number | null;
  /** flow shift of the sound (3) */
  shift_audio?: number | null;
  /** flow shift of the picture (12) */
  shift_video?: number | null;
  /** anchor or file: a masked run - this clip's latents are kept outside the regenerated part */
  source?: string | null;
  /**
   * denoising steps; below 8 only with a turbo LoRA
   * @minimum 1
   * @maximum 40
   * @default 10
   */
  steps?: number | null;
  /**
   * the text encoder
   * @default "teacher"
   */
  te?: TextEncoder | null;
  /** the text encoder sees the reference pictures */
  te_pictures?: boolean | null;
  /**
   * upscale at decode (1.5: the canvas 1.5 times); above 1 only
   * @minimum 1
   */
  upscale?: number | null;
  /**
   * with upscale
   * @default "esrgan-general"
   */
  upscaler?: Upscaler | null;
  /**
   * a multiple of 32; width x height at most 1032192 pixels (768 x 1344); video.canvases.list has the tested ones
   * @minimum 256
   * @maximum 1344
   * @default 768
   * @multipleOf 32
   */
  width?: number | null;
  /** other keys */
  [key: string]: unknown;
}

/** What `wait` takes */
export interface WaitReq {
  /** the status version the caller has: it answers when the status is another (or at timeout_s) */
  version?: string | null;
  /**
   * seconds at most
   * @minimum 0
   * @maximum 60
   * @default 30
   */
  timeout_s?: number | null;
}

/** The status, and whether it changed from the version given */
export interface Waited {
  /** nothing running */
  idle: boolean;
  /** the running or last clip; null: nothing made since the studio started */
  job?: Clip | null;
  pct?: number | null;
  stage?: string | null;
  done?: boolean | null;
  /** failed or cancelled: what happened, and the engine's last lines */
  error?: string | null;
  failure?: Failure | null;
  /** the card the clip runs on */
  gpu?: unknown | null;
  exited?: boolean | null;
  /** 0 done, 1 failed (once it ended) */
  rc?: number | null;
  elapsed?: number | null;
  /** seconds left, estimated */
  eta?: number | null;
  rms?: number | null;
  /** the stages' seconds, by the legacy record's labels (TOTAL, video decoded ...) */
  times?: Record<string, number> | null;
  frames?: number | null;
  steps_done?: number | null;
  steps_total?: number | null;
  per_step?: number | null;
  metrics?: unknown[] | null;
  /** done: the clip (/out/<name>.mp4) */
  file?: string | null;
  /** while it samples: a picture of the shot so far (PNG URL, new each step) */
  preview?: string | null;
  /** the engine's last 12 lines */
  engine_log?: string[] | null;
  /** the queue's labels, in order */
  queue: string[];
  queue_items: QueueItem[];
  /** the whole queue held */
  paused: boolean;
  paused_projects: string[];
  paused_batches: string[];
  projects: Project[];
  /** the queue's projects, then the finished clips', newest first */
  all_projects: string[];
  llm: LlmStatus;
  /** changes when the status does (video.wait waits for that) */
  version: string;
  queue_len: number;
  stale: boolean;
  changed: boolean;
}

/** Every method: what it takes and what it answers. */
export interface Methods {
  /** What the studio is doing: the clip being made (stage, progress, its preview), the queue, the projects */
  status: { req: Record<string, never>; resp: Status };
  /** The status once it changes from `version` (or at timeout_s): a long poll */
  wait: { req: WaitReq; resp: Waited };
  /** The card the studio runs on: its memory, power, temperatures, link */
  gpu: { req: Record<string, never>; resp: Gpu };
  /** The clips made, their time and energy, by project */
  summary: { req: Record<string, never>; resp: Summary };
  /** The engines (quantizations) the daemon offers */
  "engines.list": { req: Record<string, never>; resp: Engines };
  /** The canvases (sizes) that fit, by engine */
  "canvases.list": { req: Record<string, never>; resp: Canvases };
  /** What fits on the cards: length and size by engine, measured and estimated */
  plan: { req: Record<string, never>; resp: Plan };
  /** The prompt templates */
  "templates.list": { req: Record<string, never>; resp: Templates };
  /** A clip: started at once, or queued (queue: true) when one is running; a reentrant_id's clip is answered as it is. It takes what the front door's video.generate takes (which passes its body on here) */
  generate: { req: VideoGenerateReq; resp: Generated };
  /** The clips waiting */
  "queue.list": { req: Record<string, never>; resp: QueueList };
  /** Holds the queue, a project or a batch (their clips wait until resumed) */
  "queue.pause": { req: Scope; resp: HoldResult };
  /** Releases the queue (every project and batch too), a project or a batch */
  "queue.resume": { req: Scope; resp: HoldResult };
  /** Drops the clips waiting: all, a project's or a batch's */
  "queue.clear": { req: Scope; resp: Cleared };
  /** Stops the clip running, or one by its label (running: stopped; queued: dropped) */
  cancel: { req: LabelReq; resp: Cancelled };
  /** Drops a queued clip */
  "queue.remove": { req: RemoveReq; resp: Removed };
  /** Moves a queued clip (and sets its priority) */
  "queue.move": { req: MoveReq; resp: Moved };
  /** The chat model the prompt writer uses: set (and started), or none */
  "llm.mode": { req: ModeReq; resp: LlmStatus };
  /** A project as a scene document (its clips' final prompts and settings) */
  "scene.export": { req: ProjectRef; resp: Scene };
  /** A scene document queued (as a project; held with paused) */
  "scene.import": { req: SceneImport; resp: Imported };
  /** The films joined */
  "films.list": { req: Record<string, never>; resp: Films };
  /** A project's clips in order: made, running, queued */
  timeline: { req: ProjectRef; resp: Timeline };
  /** The projects in the queue */
  "projects.list": { req: Record<string, never>; resp: Projects };
  /** The clips made, newest first */
  "jobs.list": { req: JobsReq; resp: Jobs };
  /** A clip's record (its request, its times, its energy) */
  "jobs.get": { req: FileName; resp: ClipRecord };
  /** A file in the clips directory: its size, hash and time */
  "files.stat": { req: FileName; resp: FileStat };
  /** A finished clip and every file of it, or an upload (never the clip being made) */
  "files.delete": { req: FileName; resp: Deleted };
}

/** The methods that take no parameters (their body may be left out). */
export type NoParamMethods = "status" | "gpu" | "summary" | "engines.list" | "canvases.list" | "plan" | "templates.list" | "queue.list" | "films.list" | "projects.list";

/** Every error's body, whatever the HTTP status: branch on `code`, never on the status (docs/RPC_RULES.md). */
export interface RpcError {
  /** what went wrong, in words */
  error: string;
  /** machine-readable: not_found, bad_payload, bad_request, conflict, busy, unavailable, unauthorized, internal, or the method's own */
  code: string;
  /** the same request may work later */
  retryable: boolean;
}

/** The project's JSON call of a method by its name. */
export type Post = (method: string, body: unknown) => Promise<any>;
/** A call that answers raw bytes (a download). */
export type PostRaw = (method: string, body: unknown) => Promise<Blob>;

export function client(post: Post, raw?: PostRaw) {
  const bytes = (m: string, b: unknown) => (raw ? raw(m, b) : Promise.reject(new Error("no raw call given")));
  void bytes;
  return {
    /** What the studio is doing: the clip being made (stage, progress, its preview), the queue, the projects */
    status: (req: Record<string, never> = {}): Promise<Status> => post("status", req),
    /** The status once it changes from `version` (or at timeout_s): a long poll */
    wait: (req: WaitReq): Promise<Waited> => post("wait", req),
    /** The card the studio runs on: its memory, power, temperatures, link */
    gpu: (req: Record<string, never> = {}): Promise<Gpu> => post("gpu", req),
    /** The clips made, their time and energy, by project */
    summary: (req: Record<string, never> = {}): Promise<Summary> => post("summary", req),
    /** The engines (quantizations) the daemon offers */
    "engines.list": (req: Record<string, never> = {}): Promise<Engines> => post("engines.list", req),
    /** The canvases (sizes) that fit, by engine */
    "canvases.list": (req: Record<string, never> = {}): Promise<Canvases> => post("canvases.list", req),
    /** What fits on the cards: length and size by engine, measured and estimated */
    plan: (req: Record<string, never> = {}): Promise<Plan> => post("plan", req),
    /** The prompt templates */
    "templates.list": (req: Record<string, never> = {}): Promise<Templates> => post("templates.list", req),
    /** A clip: started at once, or queued (queue: true) when one is running; a reentrant_id's clip is answered as it is. It takes what the front door's video.generate takes (which passes its body on here) */
    generate: (req: VideoGenerateReq): Promise<Generated> => post("generate", req),
    /** The clips waiting */
    "queue.list": (req: Record<string, never> = {}): Promise<QueueList> => post("queue.list", req),
    /** Holds the queue, a project or a batch (their clips wait until resumed) */
    "queue.pause": (req: Scope): Promise<HoldResult> => post("queue.pause", req),
    /** Releases the queue (every project and batch too), a project or a batch */
    "queue.resume": (req: Scope): Promise<HoldResult> => post("queue.resume", req),
    /** Drops the clips waiting: all, a project's or a batch's */
    "queue.clear": (req: Scope): Promise<Cleared> => post("queue.clear", req),
    /** Stops the clip running, or one by its label (running: stopped; queued: dropped) */
    cancel: (req: LabelReq): Promise<Cancelled> => post("cancel", req),
    /** Drops a queued clip */
    "queue.remove": (req: RemoveReq): Promise<Removed> => post("queue.remove", req),
    /** Moves a queued clip (and sets its priority) */
    "queue.move": (req: MoveReq): Promise<Moved> => post("queue.move", req),
    /** The chat model the prompt writer uses: set (and started), or none */
    "llm.mode": (req: ModeReq): Promise<LlmStatus> => post("llm.mode", req),
    /** A project as a scene document (its clips' final prompts and settings) */
    "scene.export": (req: ProjectRef): Promise<Scene> => post("scene.export", req),
    /** A scene document queued (as a project; held with paused) */
    "scene.import": (req: SceneImport): Promise<Imported> => post("scene.import", req),
    /** The films joined */
    "films.list": (req: Record<string, never> = {}): Promise<Films> => post("films.list", req),
    /** A project's clips in order: made, running, queued */
    timeline: (req: ProjectRef): Promise<Timeline> => post("timeline", req),
    /** The projects in the queue */
    "projects.list": (req: Record<string, never> = {}): Promise<Projects> => post("projects.list", req),
    /** The clips made, newest first */
    "jobs.list": (req: JobsReq): Promise<Jobs> => post("jobs.list", req),
    /** A clip's record (its request, its times, its energy) */
    "jobs.get": (req: FileName): Promise<ClipRecord> => post("jobs.get", req),
    /** A file in the clips directory: its size, hash and time */
    "files.stat": (req: FileName): Promise<FileStat> => post("files.stat", req),
    /** A finished clip and every file of it, or an upload (never the clip being made) */
    "files.delete": (req: FileName): Promise<Deleted> => post("files.delete", req),
  };
}

/** What a call answers: its result, or the error as data (code: invalid_request, invalid_param, not_found, busy, not_running, unknown_method, internal). */
export type Envelope<T> = { ok: true; result: T } | { ok: false; error: { code: string; message: string } };

/** A call of the studio's at `base` (its own port, or under the front door's /open/<id>/): the result, or an Error of the envelope's words. */
export function studio(base: string) {
  return client(async (method: string, body: unknown) => {
    const r = await fetch(`${base}/rpc/${method}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body ?? {}) });
    const e = (await r.json()) as Envelope<unknown>;
    if (!e.ok) throw new Error(`${e.error.code}: ${e.error.message}`);
    return e.result;
  });
}
